+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta http-equiv="X-UA-Compatible" content="IE=edge">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Kanban Task Board</title>
+    <link rel="preconnect" href="https://fonts.googleapis.com">
+    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
+    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@100;200;300;400;500;600;700;800;900&family=JetBrains+Mono:wght@100;200;300;400;500;600;700;800;900&display=swap" rel="stylesheet">
+    <style>
+        body {
+            font-family: 'Inter', sans-serif;
+            background-color: #0F172A;
+        }
+        .container {
+            max-width: 600px;
+            padding: 28px;
+            border-radius: 20px;
+            background: rgba(15, 23, 42, 0.8);
+            backdrop-filter: blur(20px);
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.35);
+        }
+        .task-board {
+            display: flex;
+            flex-direction: column;
+            align-items: center;
+            padding: 20px;
+        }
+        .task-list {
+            display: flex;
+            flex-direction: column;
+            align-items: center;
+            padding: 20px;
+        }
+        .task {
+            background-color: #F8FAFC;
+            padding: 10px;
+            border-radius: 10px;
+            margin-bottom: 10px;
+            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
+        }
+        .task:hover {
+            transform: scale(1.05);
+            transition: all 0.2s ease-in-out;
+        }
+        .add-task-button {
+            background-color: #38BDF8;
+            color: #F8FAFC;
+            padding: 10px 20px;
+            border: none;
+            border-radius: 10px;
+            cursor: pointer;
+        }
+        .add-task-button:hover {
+            background-color: #2A86C9;
+            transition: all 0.2s ease-in-out;
+        }
+    </style>
+</head>
+<body>
+    <div class="container">
+        <h1 style="font-family: 'JetBrains Mono', monospace; color: #38BDF8; font-size: 24px; font-weight: bold; margin-bottom: 20px;">Kanban Task Board</h1>
+        <div class="task-board">
+            <div class="task-list">
+                <h2 style="font-family: 'Inter', sans-serif; color: #F8FAFC; font-size: 18px; font-weight: bold; margin-bottom: 10px;">To-Do</h2>
+                <div id="to-do-tasks" class="task-list"></div>
+            </div>
+            <div class="task-list">
+                <h2 style="font-family: 'Inter', sans-serif; color: #F8FAFC; font-size: 18px; font-weight: bold; margin-bottom: 10px;">In Progress</h2>
+                <div id="in-progress-tasks" class="task-list"></div>
+            </div>
+            <div class="task-list">
+                <h2 style="font-family: 'Inter', sans-serif; color: #F8FAFC; font-size: 18px; font-weight: bold; margin-bottom: 10px;">Done</h2>
+                <div id="done-tasks" class="task-list"></div>
+            </div>
+        </div>
+        <button class="add-task-button" onclick="addTask()">Add Task</button>
+    </div>
+    <script>
+        let tasks = [];
+        let toDoTasks = [];
+        let inProgressTasks = [];
+        let doneTasks = [];
+        
+        function addTask() {
+            let taskName = prompt("Enter task name");
+            if (taskName !== null && taskName !== "") {
+                let task = {
+                    name: taskName,
+                    status: "to-do"
+                };
+                tasks.push(task);
+                toDoTasks.push(task);
+                updateTaskList();
+            }
+        }
+        
+        function updateTaskList() {
+            let toDoHtml = "";
+            let inProgressHtml = "";
+            let doneHtml = "";
+            
+            toDoTasks.forEach(task => {
+                toDoHtml += `<div class="task">${task.name}</div>`;
+            });
+            inProgressTasks.forEach(task => {
+                inProgressHtml += `<div class="task">${task.name}</div>`;
+            });
+            doneTasks.forEach(task => {
+                doneHtml += `<div class="task">${task.name}</div>`;
+            });
+            
+            document.getElementById("to-do-tasks").innerHTML = toDoHtml;
+            document.getElementById("in-progress-tasks").innerHTML = inProgressHtml;
+            document.getElementById("done-tasks").innerHTML = doneHtml;
+        }
+    </script>
+</body>
+</html>

